/* ==============================================================
   Objeto ..........: dbo.BI_OPORT_FUNIL
   Tipo ............: VIEW
   Criado em .......: 2015-09-09 20:08:05
   Modificado em ...: 2016-03-22 19:20:04
   Linhas ..........: 1
   Escreve em tabela: nao
   Tabelas referidas: IV_PROCDADO, IV_PROCESSO, IV_PROCPERSP, IV_PROCSTATMONIT
   Fonte: banco CRM (Vortice CRM / Tracbel) - extracao somente leitura
   ============================================================== */

CREATE VIEW BI_OPORT_FUNIL AS  SELECT PDD.PROCESSO AS ONE_PROCESSO,         PDD.CAMPANHA AS ONE_CAMPANHAFUN,         'Monitoramento' as FUNIL_TIPO,         1 AS FUNIL_VALOR    FROM IV_PROCDADO PDD    JOIN IV_PROCESSO PRC      ON PRC.PROCESSO = PDD.PROCESSO    JOIN IV_PROCDADO PMON ON PMON.CODPROCESSO = 9400 AND PMON.PROCESSO = PDD.PROCESSOPAI    LEFT JOIN IV_PROCPERSP PESP      ON PESP.CODPROCESSO = PDD.CODPROCESSO     AND PESP.PERSPORDEM = PRC.PERSPECTIVA   WHERE PDD.CODPROCESSO IN (7)     AND PRC.FASEORDEM > 35     AND  ISNULL(PRC.DTAREALIZACAO, PDD.DTAULTRESULTADO) >= convert(datetime,'01/01/2010',103)    union    SELECT PDD.PROCESSO AS ONE_PROCESSO,        PDD.CAMPANHA AS ONE_CAMPANHAFUN,         'Oportunidade' as FUNIL_TIPO,         1 AS FUNIL_VALOR    FROM IV_PROCDADO PDD    JOIN IV_PROCESSO PRC      ON PRC.PROCESSO = PDD.PROCESSO    LEFT JOIN IV_PROCPERSP PESP      ON PESP.CODPROCESSO = PDD.CODPROCESSO     AND PESP.PERSPORDEM = PRC.PERSPECTIVA   WHERE PDD.CODPROCESSO IN (7)     AND PRC.FASEORDEM > 35     AND  ISNULL(PRC.DTAREALIZACAO, PDD.DTAULTRESULTADO) >= convert(datetime,'01/01/2010',103)     union     SELECT PDD.PROCESSO AS ONE_PROCESSO,        PDD.CAMPANHA AS ONE_CAMPANHAFUN,         'Pedido' as FUNIL_TIPO,          1   AS FUNIL_VALOR    FROM IV_PROCDADO PDD    JOIN IV_PROCSTATMONIT PSM ON PSM.PROCESSO = PDD.PROCESSO AND PSM.STATUS = 'PEDIDO REALIZADO'    JOIN IV_PROCESSO PRC      ON PRC.PROCESSO = PDD.PROCESSO    LEFT JOIN IV_PROCPERSP PESP      ON PESP.CODPROCESSO = PDD.CODPROCESSO     AND PESP.PERSPORDEM = PRC.PERSPECTIVA   WHERE PDD.CODPROCESSO IN (7)     AND PRC.FASEORDEM > 35     AND  ISNULL(PRC.DTAREALIZACAO, PDD.DTAULTRESULTADO) >= convert(datetime,'01/01/2010',103)   UNION   SELECT PDD.PROCESSO AS ONE_PROCESSO,        PDD.CAMPANHA AS ONE_CAMPANHAFUN,         'Pedido' as FUNIL_TIPO,         1 AS FUNIL_VALOR    FROM IV_PROCDADO PDD    JOIN IV_PROCESSO PRC      ON PRC.PROCESSO = PDD.PROCESSO    LEFT JOIN IV_PROCPERSP PESP      ON PESP.CODPROCESSO = PDD.CODPROCESSO     AND PESP.PERSPORDEM = PRC.PERSPECTIVA   WHERE PDD.CODPROCESSO IN (7)     AND PRC.FASEORDEM > 35     AND PRC.STATUS != 'VENDA PERDIDA'     AND PRC.STATUS != 'DESISTIU DA COMPRA'     AND  ISNULL(PRC.DTAREALIZACAO, PDD.DTAULTRESULTADO) >= convert(datetime,'01/01/2010',103)   union   SELECT PDD.PROCESSO AS ONE_PROCESSO,        PDD.CAMPANHA AS ONE_CAMPANHAFUN,         'Venda' as FUNIL_TIPO,         1 AS FUNIL_VALOR    FROM IV_PROCDADO PDD    JOIN IV_PROCESSO PRC      ON PRC.PROCESSO = PDD.PROCESSO    LEFT JOIN IV_PROCPERSP PESP      ON PESP.CODPROCESSO = PDD.CODPROCESSO     AND PESP.PERSPORDEM = PRC.PERSPECTIVA   WHERE PDD.CODPROCESSO IN (7)     AND PRC.FASEORDEM > 35     AND PRC.STATUS != 'VENDA PERDIDA'     AND PRC.STATUS != 'DESISTIU DA COMPRA'     AND  ISNULL(PRC.DTAREALIZACAO, PDD.DTAULTRESULTADO) >= convert(datetime,'01/01/2010',103)